    """(top, left, bottom, right) of a list of positions; None if empty."""
    if not pos:
        return None
    return (min(i for i, _ in pos), min(j for _, j in pos),
            max(i for i, _ in pos), max(j for _, j in pos))

def fill_border(grid, top, left, bottom, right, color, skip=()):
    """Set color on the border of the given rectangle except where the cell's value is in skip."""
    g = [row[:] for row in grid]
    for j in range(left, right + 1):
